mapper.select:
SELECT
    j.*,
    c.name AS company_name,
    c.logo AS company_logo,
    c.industry AS company_industry,
    c.scale AS company_scale
FROM job j
LEFT JOIN company c ON j.company_id = c.id
WHERE j.deleted = 0 AND j.status = 'OPEN'

    AND (
        j.title LIKE CONCAT('%', #{keyword}, '%')
        OR j.keywords LIKE CONCAT('%', #{keyword}, '%')
        OR j.description LIKE CONCAT('%', #{keyword}, '%')
        OR j.requirements LIKE CONCAT('%', #{keyword}, '%')
        OR c.name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND j.city = #{city}


    AND j.job_type = #{jobType}


    AND j.max_salary  >=  #{minSalary}


    AND j.min_salary  <=  #{maxSalary}


    AND j.experience = #{experience}


    AND j.education = #{education}

ORDER BY j.created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM job j
LEFT JOIN company c ON j.company_id = c.id
WHERE j.deleted = 0 AND j.status = 'OPEN'

    AND (
        j.title LIKE CONCAT('%', #{keyword}, '%')
        OR j.keywords LIKE CONCAT('%', #{keyword}, '%')
        OR j.description LIKE CONCAT('%', #{keyword}, '%')
        OR j.requirements LIKE CONCAT('%', #{keyword}, '%')
        OR c.name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND j.city = #{city}


    AND j.job_type = #{jobType}


    AND j.max_salary  >=  #{minSalary}


    AND j.min_salary  <=  #{maxSalary}


    AND j.experience = #{experience}


    AND j.education = #{education}
